blocks.mermaid:
flowchart TD
  Q["Expresión del SELECT"] --> A{"¿Va dentro de un agregado?"}
  A -->|"Sí"| OK1["Válida"]
  A -->|"No"| B{"¿Está en el GROUP BY o se calcula<br/>solo con columnas agrupadas?"}
  B -->|"Sí"| OK2["Válida"]
  B -->|"No"| F{"¿Es de una tabla cuya clave<br/>primaria está en el GROUP BY?"}
  F -->|"Sí"| OK3["Válida: dependencia funcional"]
  F -->|"No"| E["ERROR: must appear in the GROUP BY clause<br/>or be used in an aggregate function"]

